begin;
create table public.forgecost_workspaces(user_id uuid primary key references auth.users(id) on delete cascade,data jsonb not null,version bigint not null default 1 check(version>0),updated_at timestamptz not null default now(),constraint workspace_shape check(jsonb_typeof(data)='object' and jsonb_typeof(data->'products')='array' and jsonb_typeof(data->'inputs')='array' and jsonb_typeof(data->'categories')='array' and jsonb_typeof(data->'history')='array' and jsonb_typeof(data->'laborSettings')='object')));
alter table public.forgecost_workspaces enable row level security;alter table public.forgecost_workspaces force row level security;revoke all on public.forgecost_workspaces from public,anon,authenticated;grant select,insert,update on public.forgecost_workspaces to authenticated;
create policy own_select on public.forgecost_workspaces for select to authenticated using((select auth.uid())=user_id);create policy own_insert on public.forgecost_workspaces for insert to authenticated with check((select auth.uid())=user_id);create policy own_update on public.forgecost_workspaces for update to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
create function public.forgecost_save(p_data jsonb,p_expected_version bigint) returns jsonb language plpgsql security invoker set search_path='' as $$ declare saved public.forgecost_workspaces;begin if auth.uid() is null then raise exception 'Authentication required' using errcode='28000';end if;if p_expected_version=0 then insert into public.forgecost_workspaces(user_id,data) values(auth.uid(),p_data) on conflict(user_id) do nothing returning * into saved;else update public.forgecost_workspaces set data=p_data,version=version+1,updated_at=now() where user_id=auth.uid() and version=p_expected_version returning * into saved;end if;if saved.user_id is null then raise exception 'Workspace changed' using errcode='40001';end if;return jsonb_build_object('version',saved.version,'updated_at',saved.updated_at);end;$$;
revoke all on function public.forgecost_save(jsonb,bigint) from public,anon;grant execute on function public.forgecost_save(jsonb,bigint) to authenticated;commit;
